import{_ as e,c as l,a,o as i}from"./app-B9IyngIV.js";const d={};function p(h,t){return i(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="ai搭建" tabindex="-1"><a class="header-anchor" href="#ai搭建"><span>AI搭建</span></a></h1><div style="background:#f8f9fa;padding:12px 16px;border-left:3px solid #4CAF50;margin-bottom:16px;border-radius:0 4px 4px 0;font-size:0.9rem;"><div style="display:flex;align-items:center;gap:30px;flex-wrap:wrap;"><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">📅</span><span>2025-07-06</span></div><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">✍️</span><span>Jixer</span></div></div></div><h2 id="技术方案" tabindex="-1"><a class="header-anchor" href="#技术方案"><span>技术方案</span></a></h2><ul><li><p>方案一：直接调用 DeepsSeek 官方或者 OpenAi 提供的 API 接口</p></li><li><p>方案二：本地部署</p></li></ul><h2 id="方案一" tabindex="-1"><a class="header-anchor" href="#方案一"><span>方案一</span></a></h2><p>优点：简单能直接上手、成本低</p><p>缺点：数据传输不安全</p><h3 id="deepseek-api" tabindex="-1"><a class="header-anchor" href="#deepseek-api"><span>DeepSeek API</span></a></h3><p>官方文档：https://api-docs.deepseek.com/zh-cn/</p><p><strong>调用收费规则</strong></p><p>Token 是模型用来表示自然语言文本的的最小单位，可以是一个词、一个数字或一个标点符号等，将根据模型输入和输出（包括提问和 AI 回答）的总 token 数进行计量计费</p><p>一般情况下模型中 token 和字数的换算比例大致如下：</p><ul><li>1 个英文字符 ≈ 0.3 个 token</li><li>1 个中文字符 ≈ 0.6 个 token</li></ul><p>DeepSeek 提供的两种模型对比</p><p><img src="https://gitee.com/lijunxi666/picture-bed/raw/master/customer-service/image-20250630164042925.png" alt="image-20250630164042925"></p><ul><li>Json Output：支持 Json 格式输出</li><li>Function Calling：让模型能够调用外部工具，来增强自身能力</li><li>对话前缀续写（Beta）：用户可以提供 assistant 开头的消息，来让模型补全其余的消息</li><li>FIM 补全（Beta）：用户可以提供前缀和后缀（可选），模型来补全中间的内容</li></ul><p><strong>扣减费用 = token 消耗量 × 模型单价</strong></p><h3 id="openai-api" tabindex="-1"><a class="header-anchor" href="#openai-api"><span>OpenAi API</span></a></h3><p>暂不考虑</p><h2 id="方案二" tabindex="-1"><a class="header-anchor" href="#方案二"><span>方案二</span></a></h2><p>优点：数据具有安全性</p><p>缺点：部署复杂、成本高</p><h3 id="大语言模型参考配置" tabindex="-1"><a class="header-anchor" href="#大语言模型参考配置"><span>大语言模型参考配置</span></a></h3><p>参考网站：https://blog.csdn.net/2401_85343303/article/details/145452011</p><p><strong>1. DeepSeek-R1-1.5B</strong></p><table><thead><tr><th>CPU</th><th>内存</th><th>硬盘</th><th>显卡</th></tr></thead><tbody><tr><td>最低4核</td><td>8GB+</td><td>3GB+（模型大小1.5-2GB）</td><td>非必需</td></tr></tbody></table><p>适用场景：</p><ul><li>低资源设备部署（如树莓派、旧款笔记本）</li><li>实时文本生成（聊天机器人、简单问答）</li><li>嵌入式系统或物联网设备</li></ul><hr><p><strong>2. DeepSeek-R1-7B</strong></p><table><thead><tr><th>CPU</th><th>内存</th><th>硬盘</th><th>显卡</th></tr></thead><tbody><tr><td>8核以上（推荐现代多核）</td><td>16GB+</td><td>8GB+（模型4-5GB）</td><td>推荐8GB+（如RTX 3070/4060）</td></tr></tbody></table><p>适用场景：</p><ul><li>本地开发测试（中小型企业）</li><li>中等复杂度NLP任务（文本摘要、翻译）</li><li>轻量级多轮对话系统</li></ul><hr><p><strong>3. DeepSeek-R1-8B</strong></p><table><thead><tr><th>CPU</th><th>内存</th><th>硬盘</th><th>显卡</th></tr></thead><tbody><tr><td>同7B，需求高10-20%</td><td>同7B+20%</td><td>同7B+20%</td><td>同7B+20%</td></tr></tbody></table><p>适用场景：</p><ul><li>需更高精度的轻量级任务（如代码生成、逻辑推理）</li></ul><hr><p><strong>4. DeepSeek-R1-14B</strong></p><table><thead><tr><th>CPU</th><th>内存</th><th>硬盘</th><th>显卡</th></tr></thead><tbody><tr><td>12核以上</td><td>32GB+</td><td>15GB+</td><td>16GB+（如RTX 4090/A5000）</td></tr></tbody></table><p>适用场景：</p><ul><li>企业级复杂任务（合同分析、报告生成）</li><li>长文本理解与生成（书籍/论文辅助写作）</li></ul><hr><p><strong>5. DeepSeek-R1-32B</strong></p><table><thead><tr><th>CPU</th><th>内存</th><th>硬盘</th><th>显卡</th></tr></thead><tbody><tr><td>16核以上（如Ryzen 9/i9）</td><td>64GB+</td><td>30GB+</td><td>24GB+（如A100 40GB/双3090）</td></tr></tbody></table><p>适用场景：</p><ul><li>高精度专业领域任务（医疗/法律咨询）</li><li>多模态任务预处理（需结合其他框架）</li></ul><hr><p><strong>6. DeepSeek-R1-70B</strong></p><table><thead><tr><th>CPU</th><th>内存</th><th>硬盘</th><th>显卡</th></tr></thead><tbody><tr><td>32核以上（服务器级）</td><td>128GB+</td><td>70GB+</td><td>多卡（如2xA100 80GB/4x4090）</td></tr></tbody></table><p>适用场景：</p><ul><li>科研机构/大型企业（金融预测、大规模数据分析）</li><li>高复杂度生成任务（创意写作、算法设计）</li></ul><hr><p><strong>7. DeepSeek-R1-671B</strong></p><table><thead><tr><th>CPU</th><th>内存</th><th>硬盘</th><th>显卡</th></tr></thead><tbody><tr><td>64核+（服务器集群）</td><td>512GB+</td><td>300GB+</td><td>多节点（如8xA100/H100）</td></tr></tbody></table><p>适用场景：</p><ul><li>国家级/超大规模AI研究（气候建模、基因组分析）</li><li>通用人工智能（AGI）探索</li></ul><h3 id="其他配置" tabindex="-1"><a class="header-anchor" href="#其他配置"><span>其他配置</span></a></h3><ul><li>ollama：用于运行 DeepSeek 大语言模型</li></ul>',60)])])}const r=e(d,[["render",p]]),s=JSON.parse('{"path":"/ai/AI%E6%90%AD%E5%BB%BA.html","title":"AI搭建","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"技术方案","slug":"技术方案","link":"#技术方案","children":[]},{"level":2,"title":"方案一","slug":"方案一","link":"#方案一","children":[{"level":3,"title":"DeepSeek API","slug":"deepseek-api","link":"#deepseek-api","children":[]},{"level":3,"title":"OpenAi API","slug":"openai-api","link":"#openai-api","children":[]}]},{"level":2,"title":"方案二","slug":"方案二","link":"#方案二","children":[{"level":3,"title":"大语言模型参考配置","slug":"大语言模型参考配置","link":"#大语言模型参考配置","children":[]},{"level":3,"title":"其他配置","slug":"其他配置","link":"#其他配置","children":[]}]}],"git":{},"filePathRelative":"ai/AI搭建.md"}');export{r as comp,s as data};
